import React, { Suspense } from 'react';
import { BrowserRouter as Router, Routes, Route, Navigate } from 'react-router-dom';
import { ThemeProvider } from '@mui/material/styles';
import { CssBaseline, Box, Typography } from '@mui/material';
import { ToastContainer } from 'react-toastify';
import 'react-toastify/dist/ReactToastify.css';

import { AuthProvider } from './context/AuthContext';
import ErrorBoundary from './components/common/ErrorBoundary';
import DemoHelper from './components/common/DemoHelper';
import DemoModeToggle from './components/common/DemoModeToggle';
import ProtectedRoute from './components/auth/ProtectedRoute';
import theme from './theme/theme';

// Lazy load pages
import { LoadingFallback } from './components/lazy/LazyLoadWrapper';
const LazyLogin = React.lazy(() => import('./pages/Login'));
const LazyDashboard = React.lazy(() => import('./pages/Dashboard'));
const LazyFloorPlan = React.lazy(() => import('./pages/FloorPlan'));
const LazySurveys = React.lazy(() => import('./pages/Surveys'));
const LazySettings = React.lazy(() => import('./pages/Settings'));

// Fallback UI when backend is unavailable
const FallbackUI = () => (
  <Box
    display="flex"
    flexDirection="column"
    justifyContent="center"
    alignItems="center"
    minHeight="100vh"
    p={3}
    sx={{ textAlign: 'center' }}
  >
    <Typography variant="h4" color="error" gutterBottom>
      Service Unavailable
    </Typography>
    <Typography variant="body1" color="text.secondary" paragraph>
      We're experiencing technical difficulties. Please try again later.
    </Typography>
    <button
      onClick={() => window.location.reload()}
      style={{
        padding: '12px 24px',
        backgroundColor: '#1976d2',
        color: 'white',
        border: 'none',
        borderRadius: '8px',
        cursor: 'pointer',
        marginTop: '16px',
      }}
    >
      Refresh Page
    </button>
  </Box>
);

// Error boundary for the entire app
class AppErrorBoundary extends React.Component {
  constructor(props) {
    super(props);
    this.state = { hasError: false };
  }

  static getDerivedStateFromError(error) {
    return { hasError: true };
  }

  componentDidCatch(error, errorInfo) {
    // Log error to monitoring service in production
    if (process.env.NODE_ENV === 'production') {
      // Send to error reporting service
      console.error('Application Error:', error, errorInfo);
    }
  }

  render() {
    if (this.state.hasError) {
      return <FallbackUI />;
    }

    return this.props.children;
  }
}

function App() {
  return (
    <ThemeProvider theme={theme}>
      <CssBaseline />
      <AppErrorBoundary>
        <AuthProvider>
          <Router>
            <Routes>
              {/* Public Routes */}
              <Route 
                path="/login" 
                element={
                  <Suspense fallback={<LoadingFallback />}>
                    <LazyLogin />
                  </Suspense>
                } 
              />

              {/* Protected Routes */}
              <Route
                path="/dashboard"
                element={
                  <ProtectedRoute>
                    <Suspense fallback={<LoadingFallback />}>
                      <LazyDashboard />
                    </Suspense>
                  </ProtectedRoute>
                }
              />
              <Route
                path="/floor-plan"
                element={
                  <ProtectedRoute>
                    <Suspense fallback={<LoadingFallback />}>
                      <LazyFloorPlan />
                    </Suspense>
                  </ProtectedRoute>
                }
              />
              <Route
                path="/surveys"
                element={
                  <ProtectedRoute>
                    <Suspense fallback={<LoadingFallback />}>
                      <LazySurveys />
                    </Suspense>
                  </ProtectedRoute>
                }
              />
              <Route
                path="/settings"
                element={
                  <ProtectedRoute requiredRoles={['ROLE_SUPER_ADMIN', 'ROLE_ORG_ADMIN']}>
                    <Suspense fallback={<LoadingFallback />}>
                      <LazySettings />
                    </Suspense>
                  </ProtectedRoute>
                }
              />

              {/* Default redirect */}
              <Route path="/" element={<Navigate to="/dashboard" replace />} />

              {/* Catch all route */}
              <Route path="*" element={<Navigate to="/dashboard" replace />} />
            </Routes>

            {/* Demo Mode Toggle */}
            <DemoModeToggle />

            {/* Demo Helper (Development Only) */}
            <DemoHelper />
          </Router>

          {/* Toast Container */}
          <ToastContainer
            position="top-right"
            autoClose={5000}
            hideProgressBar={false}
            newestOnTop={false}
            closeOnClick
            rtl={false}
            pauseOnFocusLoss
            draggable
            pauseOnHover
            theme="light"
          />
        </AuthProvider>
      </AppErrorBoundary>
    </ThemeProvider>
  );
}

export default App;
